SELECT c.cursor, c.entity_id AS tender_id, c.changed_at, t.source, t.kind, t.created_at, t.current_seq, (SELECT COUNT(*) FROM changes c2 WHERE c2.entity_kind = 'tender' AND c2.entity_id = c.entity_id AND c2.version_seq IS NOT NULL AND c2.changed_at = c.changed_at AND c2.cursor > 958810037 AND c2.cursor < c.cursor) AS paired_seq_rows, (SELECT MIN(c2.version_seq) FROM changes c2 WHERE c2.entity_kind = 'tender' AND c2.entity_id = c.entity_id AND c2.version_seq IS NOT NULL AND c2.changed_at = c.changed_at AND c2.cursor > 958810037 AND c2.cursor < c.cursor) AS paired_min_seq, (SELECT COUNT(*) FROM tender_version_lots l WHERE l.tender_id = c.entity_id AND l.seq = t.current_seq) AS head_lots FROM changes c CROSS JOIN tenders t ON t.id = c.entity_id WHERE c.cursor > 958825037 AND c.cursor <= 958830037 AND +c.entity_kind = 'tender' AND c.version_seq IS NULL AND +c.op = 'changed' ORDER BY c.cursor LIMIT 1000
